INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'es-ES', 'name', 'Política de privacidad', 'reviewed', SHA2('隐私协议', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'es-ES', 'value', '<h2>Política de privacidad</h2><p>Gracias por utilizar esta aplicación. Valoramos y protegemos su información personal y la procesamos solo según sea necesario para proporcionar acceso a la cuenta, funciones de la aplicación y servicio al cliente.</p><h3>I. Uso de la información</h3><p>Utilizamos su información de acuerdo con las leyes aplicables y esta política, y no la usaremos para fines no relacionados.</p><h3>II. Tus Derechos</h3><p>Puedes acceder, corregir o eliminar tu información personal de acuerdo con la ley, o contactarnos a través de los canales publicados en la aplicación.</p>', 'reviewed', SHA2('<h2>隐私政策</h2><p>感谢您使用本应用。我们重视并保护您的个人信息，仅在提供账号登录、应用功能和客户服务所必需的范围内处理相关信息。</p><h3>一、信息使用</h3><p>我们会按照法律法规和本协议约定使用您的信息，不会将其用于无关目的。</p><h3>二、您的权利</h3><p>您可以依法查询、更正、删除个人信息，或通过应用内公布的渠道联系我们。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'es-ES', 'name', 'Términos de servicio', 'reviewed', SHA2('服务条款', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'es-ES', 'value', '<h2>Términos de servicio</h2><p>Bienvenido a esta aplicación. Lea y comprenda este acuerdo y las reglas relacionadas antes de utilizar la aplicación. Al utilizar los servicios de la aplicación, usted acepta cumplirlos.</p><h3>I. Uso del servicio</h3><p>Utilice cada función de forma legal y de acuerdo con las instrucciones de la página. No debe utilizar esta aplicación para actividades ilegales o actividades que infrinjan los derechos de otros.</p><h3>II. Cambios al Acuerdo</h3><p>Podemos actualizar este acuerdo de acuerdo con los cambios en el negocio, las leyes y regulaciones, y mostraremos la versión actualizada en la aplicación.</p>', 'reviewed', SHA2('<h2>服务条款</h2><p>欢迎使用本应用。使用本应用前，请您阅读并理解本协议。您开始使用应用服务，即表示同意遵守本协议及相关规则。</p><h3>一、服务使用</h3><p>请您依法、合规并按照页面提示使用各项功能，不得利用本应用从事违法或损害他人权益的活动。</p><h3>二、协议变更</h3><p>我们会根据业务和法律法规变化更新本协议，并在应用内向您展示更新后的内容。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
